v=read(R/'verification.json');e=read(R/'kaggle-output/evaluation.json');a=read(R/'data/audit.json');s=read(R/'kaggle-output/selection.json');p=read(R/'run_provenance.json');assert v['verified']
new=e['diagnostic'];old=e['v13_same_cohort'];baseline=e['baseline']
columns=[('نسبة التقديرات ضمن ±10%','within10','pct'),('متوسط الخطأ النسبي المطلق','mape','pct'),('وسيط الخطأ النسبي','median_ape','pct'),('المئين 95 للخطأ','p95_ape','pct'),('أكبر خطأ','max_ape','pct'),('متوسط الخطأ المطلق بالدولار','mae','usd')]
