 vals=[f'{m[key]:.2%}' if fmt=='pct' else f'{m[key]:,.0f}' for m in [baseline,old,new]]
 rows+='<tr><th>'+label+'</th>'+''.join('<td>'+x+'</td>' for x in vals)+'</tr>'
